import{_ as t,o as i,c as a,a2 as n}from"./chunks/framework.7w-lhQN6.js";const u=JSON.parse('{"title":"Gemini CLI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/gemini-cli.md","filePath":"guide/gemini-cli.md","lastUpdated":1793550481000}'),s={name:"guide/gemini-cli.md"};function o(l,e,d,h,r,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="gemini-cli" tabindex="-1">Gemini CLI <a class="header-anchor" href="#gemini-cli" aria-label="Permalink to &quot;Gemini CLI&quot;">​</a></h1><p>By the end of this page Gemini CLI has the MCP Lens extension installed, so every MCP tool call in your Gemini CLI sessions is recorded locally and the <code>calls</code> column in <code>mcp-lens report</code> stops sitting at zero for servers you use through Gemini CLI.</p><h2 id="the-easy-way-let-the-vs-code-extension-do-it" tabindex="-1">The easy way: let the VS Code extension do it <a class="header-anchor" href="#the-easy-way-let-the-vs-code-extension-do-it" aria-label="Permalink to &quot;The easy way: let the VS Code extension do it&quot;">​</a></h2><p>If you use the VS Code extension, run its <code>MCP Lens: Install Hooks for All Clients</code> command and it installs this extension for you. See <a href="/MCPLens/guide/vscode-extension">VS Code Extension</a>. If you took that route, skip the manual install section below and continue at <a href="#after-installing">After installing</a>, which applies however the extension got there.</p><h2 id="install-the-extension-manually" tabindex="-1">Install the extension manually <a class="header-anchor" href="#install-the-extension-manually" aria-label="Permalink to &quot;Install the extension manually&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gemini</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extensions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/to/packages/gemini-extension</span></span></code></pre></div><p>Substitute <code>/absolute/path/to</code> with the absolute path to your clone of the repository. The extension&#39;s manifest name is <code>mcp-lens</code>, so <code>gemini extensions list</code> should show <code>mcp-lens</code> among the installed extensions afterward. Restart Gemini CLI afterward so it loads the extension and its hook registration.</p><h2 id="what-it-collects" tabindex="-1">What it collects <a class="header-anchor" href="#what-it-collects" aria-label="Permalink to &quot;What it collects&quot;">​</a></h2><p>The extension captures local-only MCP accounting metadata from Gemini CLI hook events, discarding sensitive payload fields including <code>tool_input</code>, <code>tool_response</code>, <code>llmContent</code> and <code>returnDisplay</code>. It uses only its bundled hook runner, never downloads a runtime, and never opens the MCP Lens database or the network. Events are atomically queued under <code>~/.mcplens/inbox</code>, and Gemini&#39;s original logs are never modified or moved.</p><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><p>Restart Gemini CLI so the extension and its hooks load.</p><p>To pause collection without removing the extension, disable it and restart again:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gemini</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extensions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp-lens</span></span></code></pre></div><p>This stops new capture without removing the extension. Restart Gemini CLI after changing the extension state for the change to take effect.</p><p>To remove it entirely, uninstall it with Gemini CLI&#39;s extension uninstall command and restart. Either way, it does not touch metadata already queued or any original Gemini logs.</p>',15)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
